<?php
namespace App\Http\Controllers\Api\V1;use App\Models\CandidateProfile;use App\Models\Job;use App\Models\RecruitmentCampaign;use App\Models\TalentInvitation;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class RecruitmentCampaignController{public function index(Request $r):JsonResponse{$c=$this->company($r);return response()->json(['data'=>RecruitmentCampaign::where('company_id',$c->id)->latest()->get()]);}public function store(Request $r):JsonResponse{$c=$this->company($r);$d=$r->validate(['job_id'=>['required','integer'],'name'=>['required','string','max:150'],'message'=>['nullable','string','max:2000'],'filters'=>['nullable','array'],'filters.province'=>['nullable','string','max:100'],'filters.skill'=>['nullable','string','max:100']]);Job::where('company_id',$c->id)->where('status','active')->findOrFail($d['job_id']);$q=$this->talents($c->id,$d['filters']??[]);$campaign=RecruitmentCampaign::create([...$d,'company_id'=>$c->id,'created_by'=>$r->user()->id,'matched_count'=>(clone$q)->count()]);return response()->json(['data'=>$campaign],201);}public function send(Request $r,RecruitmentCampaign $campaign):JsonResponse{$c=$this->company($r);abort_unless($campaign->company_id===$c->id&&$campaign->status==='draft',422);$users=$this->talents($c->id,$campaign->filters??[])->limit(200)->pluck('user_id');$invited=0;DB::transaction(function()use($users,$campaign,$r,&$invited):void{foreach($users as $id){$x=TalentInvitation::firstOrCreate(['job_id'=>$campaign->job_id,'candidate_user_id'=>$id],['company_id'=>$campaign->company_id,'sent_by'=>$r->user()->id,'message'=>$campaign->message,'status'=>'pending']);if($x->wasRecentlyCreated)$invited++;}$campaign->update(['status'=>'completed','invited_count'=>$invited,'sent_at'=>now()]);});return response()->json(['data'=>$campaign->fresh(),'message'=>"Campaña enviada a {$invited} perfiles con consentimiento."]);}private function talents(int $company,array $filters){$q=CandidateProfile::query()->where('talent_visibility','companies')->where('available_for_opportunities',true)->whereNotExists(fn($x)=>$x->selectRaw(1)->from('blocked_companies')->whereColumn('blocked_companies.candidate_user_id','candidate_profiles.user_id')->where('blocked_companies.company_id',$company));if(!empty($filters['province']))$q->where('province',$filters['province']);if(!empty($filters['skill']))$q->whereJsonContains('skills',$filters['skill']);return$q;}private function company(Request $r){abort_unless($r->user()->account_type==='company',403);$c=$r->user()->companies()->wherePivot('status','active')->firstOrFail();$role=$c->members()->whereKey($r->user()->id)->first()?->pivot->role;abort_unless(in_array($role,['owner','admin','recruiter']),403);return$c;}}
